// The plugin's commands: Tauri generates an allow and a deny permission for each
// (permissions/autogenerated); permissions/default.toml allows them all.
const COMMANDS: &[&str] = &[
    "read_score",
    "write_score",
    "soundfont_status",
    "install_soundfont",
    "cancel_soundfont_install",
    "read_soundfont",
    "remove_soundfont",
    "export_pdf",
    "write_export",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).build();
    // On Windows, Tauri needs version 6 of the common controls (an app's tauri-build embeds the
    // manifest that asks for them); the plugin's own test binary asks for them here, or it does not
    // start (STATUS_ENTRYPOINT_NOT_FOUND).
    if std::env::var("CARGO_CFG_TARGET_ENV").is_ok_and(|target| target == "msvc") {
        println!("cargo:rustc-link-arg=/MANIFEST:EMBED");
        println!(
            "cargo:rustc-link-arg=/MANIFESTDEPENDENCY:type='win32' name='Microsoft.Windows.Common-Controls' \
             version='6.0.0.0' processorArchitecture='*' publicKeyToken='6595b64144ccf1df' language='*'"
        );
    }
}
